"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def IntegerSquareRoot(n):
    if (n < 2):
        return n
    low = 1
    high = (n // 2)
    ans = 0
    while (low <= high):
        mid = (low + ((high - low) // 2))
        if ((mid * mid) == n):
            return mid
        elif ((mid * mid) < n):
            ans = mid
            low = (mid + 1)
        else:
            high = (mid - 1)
    return ans
